GRAM = [
("B1", "단순미래 — 약속과 계획", "« Je publierai la vidéo jeudi. » / « Elle viendra à votre table. » / « On partagera aussi. » / « Tu auras Sofiane et Moussa. » 미래형은 어미 -rai, -ras, -ra, -rons, -rez, -ront 를 동사 원형에 붙인다. 불규칙: venir → viendr-, avoir → aur-, être → ser-."),
("B1", "근접미래와 단순미래의 차이", "« Je vais goûter » (바로 직후, 근접미래) ↔ « Je goûterai » (좀 더 먼 미래·약속). « Elle viendra ce soir » 는 약속, « Je vais lui dire » 는 곧 할 행동. 둘을 섞어 쓰면 자연스럽다."),
("B2", "미래완료 — quand elle aura mangé", "« Je viens à la fin, quand elle aura mangé. » 미래의 한 시점 이전에 끝난 행동은 aura + 과거분사. quand / dès que + 미래완료 + 단순미래 틀에서 자주 쓴다."),
("B2", "명령형 + 대명사: tutoie-moi, contente-toi", "« Toi aussi, tutoie-moi. » / « Contente-toi de servir bien. » 긍정 명령에서는 대명사가 동사 뒤에 하이픈으로 붙고, moi/toi 를 쓴다. 부정이면 « Ne me tutoie pas. » 처럼 앞에 온다."),
("B1", "접속법 입문: qu'elle ait aimé ou non", "« Qu'elle ait aimé ou non, je continue la blanquette. » 양보의 접속법 과거(ait aimé). 'qu'il ait… ou non' = ~했든 말았든. 격식 있는 구문이지만 구어에서도 가끔 쓰인다."),
("A2", "대명사 y와 en의 구분: j'en ai, il y a", "« Il y a déjà des messages ! » / « Dans mon salon, j'en ai trente. » en = de + 수량 대신 쓰이는 대명사. j'en ai trente = 서른 개 있다. il y a 는 존재 표현."),
("B2", "비교·최상급 — la meilleure blanquette de ma vie", "« la meilleure blanquette de ma vie » / « la meilleure équipe de Paris » bon → le/la meilleur(e). de + 범위(de ma vie, de Paris)로 비교 범위를 한정한다."),
]

